// Flattens the SerpAPI results, removes duplicates and businesses already in the sheet.
const settings = $('Prospecting Settings').first().json;
// (the Code node sandbox has no URL class, so domains are parsed with a regex)
const domainOf = url => String(url || '').trim().replace(/^[a-z]+:\/\//i, '').split(/[\/?#:]/)[0].replace(/^www\./i, '').toLowerCase();
const known = new Set();
for (const row of $('Read Lead Sheet').all()) {
  const r = row.json;
  if (r['Lead ID']) known.add(String(r['Lead ID']));
  if (r.Website) known.add(domainOf(r.Website));
}

const places = [];
for (const item of $input.all()) {
  const res = item.json;
  if (!Array.isArray(res.local_results)) continue;
  for (const p of res.local_results) {
    const id = p.place_id || p.data_id;
    if (!id || known.has(id)) continue;
    const website = p.website ? String(p.website).split('?')[0] : '';
    const domain = website ? domainOf(website) : '';
    if (domain && known.has(domain)) continue;
    known.add(id);
    if (domain) known.add(domain);
    places.push({
      lead_id: id,
      name: p.title || '',
      category: p.type || (p.types || [])[0] || '',
      address: p.address || '',
      phone: p.phone || '',
      website,
      domain,
      rating: p.rating ?? '',
      reviews: p.reviews ?? '',
      maps_url: 'https://www.google.com/maps/place/?q=place_id:' + (p.place_id || ''),
      search: res.search_parameters?.q || '',
    });
  }
}
return places.slice(0, Number(settings.max_new_leads_per_run) || 150).map(p => ({ json: p }));

// Fetches each website in code, so the raw HTML never lands in the execution log
// (it would make every run tens of MB). Keeps emails, socials and a text excerpt.
const helpers = this.helpers;
const BAD = /\.(png|jpe?g|gif|svg|webp|css|js)$|example\.(com|org)|sentry|wixpress|godaddy|yourdomain|domain\.com|@email\.com/i;
const decode = s => s.replace(/&amp;/g, '&').replace(/&#0?64;|&commat;/g, '@').replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&nbsp;/g, ' ');

async function get(url) {
  try {
    const body = await helpers.httpRequest({ method: 'GET', url, timeout: 12000, json: false, headers: { 'User-Agent': 'Mozilla/5.0 (compatible; lead-research)', 'Accept-Language': 'id,en;q=0.8' } });
    return typeof body === 'string' ? body.slice(0, 500000) : '';
  } catch (e) {
    return null;
  }
}
function read(html, domain) {
  const clean = decode(html);
  const text = decode(html.replace(/<(script|style|noscript)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
  const found = new Set();
  for (const m of clean.matchAll(/mailto:([^"'?>\s]+)/gi)) found.add(m[1].toLowerCase());
  for (const m of text.matchAll(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi)) found.add(m[0].toLowerCase());
  const emails = [...found].filter(e => !BAD.test(e))
    .sort((a, b) => Number(b.endsWith('@' + domain)) - Number(a.endsWith('@' + domain)));
  const pick = re => (clean.match(re) || [])[0] || '';
  const contact = (clean.match(/href=["']([^"']*(contact|kontak|hubungi)[^"']*)["']/i) || [])[1] || '';
  return {
    title: ((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').trim().slice(0, 200),
    description: (clean.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)/i) || [])[1] || '',
    emails,
    instagram: pick(/https?:\/\/(www\.)?instagram\.com\/[A-Za-z0-9_.]+/i),
    linkedin: pick(/https?:\/\/(www\.)?linkedin\.com\/company\/[A-Za-z0-9_-]+/i),
    excerpt: text.slice(0, 2500),
    contact,
  };
}

const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i += 5) {
  const chunk = items.slice(i, i + 5);
  const done = await Promise.all(chunk.map(async item => {
    const p = item.json;
    if (!p.website) return { ...p, site_ok: false, site: { emails: [], excerpt: '' } };
    const html = await get(p.website);
    if (html === null) return { ...p, site_ok: false, site: { emails: [], excerpt: '' } };
    let site = read(html, p.domain);
    if (!site.emails.length && site.contact) {
      const origin = (p.website.match(/^https?:\/\/[^\/?#]+/i) || [''])[0];
      const link = /^https?:/i.test(site.contact) ? site.contact : origin + (site.contact.startsWith('/') ? '' : '/') + site.contact;
      const extra = await get(link);
      if (extra) site.emails = read(extra, p.domain).emails;
    }
    return { ...p, site_ok: true, site };
  }));
  done.forEach((json, k) => out.push({ json, pairedItem: { item: i + k } }));
}
return out;

