={{ (() => {
  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const rows = $('Build Lead Row').all().map(i => i.json);
  const searches = $('Search Google Maps').all();
  const failed = searches.filter(i => !Array.isArray(i.json.local_results)).length;
  const count = s => rows.filter(r => r.Status === s).length;
  const top = rows.filter(r => r.Status === 'New').sort((a, b) => b['Fit Score'] - a['Fit Score']).slice(0, 10);
  return '<div style="font-family:Arial,sans-serif;font-size:14px">' +
    '<p>' + searches.length + ' searches' + (failed ? ' (<b>' + failed + ' failed</b>, check the SerpAPI quota)' : '') + ' · ' + rows.length + ' new businesses · ' +
    count('New') + ' ready for outreach · ' + count('No email') + ' without email · ' + count('Low fit') + ' low fit</p>' +
    (top.length ? '<table cellpadding="6" style="border-collapse:collapse;border:1px solid #ddd"><tr><th align="left">Score</th><th align="left">Business</th><th align="left">Why</th></tr>' +
      top.map(r => '<tr><td>' + r['Fit Score'] + '</td><td><a href="' + esc(r['Maps URL']) + '">' + esc(r.Name) + '</a><br><small>' + esc(r.Segment) + '</small></td><td>' + esc(r['Fit Reason']) + '</td></tr>').join('') + '</table>' : '') +
    '<p style="color:#666">Outreach sends these on weekdays, a few per hour.</p></div>';
})() }}

