// Decides, per lead, whether to record a reply, send a first email or send a follow-up.
const cfg = $('Outreach Settings').first().json;
const stopWords = String(cfg.stop_words).split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const replies = new Map();
for (const m of $('Find Replies').all()) {
  const from = String(m.json.From ?? m.json.from ?? '');
  const email = ((from.match(/<([^>]+)>/) || [])[1] || from).trim().toLowerCase();
  if (email) replies.set(email, String(m.json.snippet ?? '').toLowerCase());
}
const leads = $input.all().map(i => i.json).filter(r => r['Lead ID']);
const out = [];
for (const lead of leads) {
  const email = String(lead.Email || '').toLowerCase();
  if (['Contacted', 'Followed up'].includes(lead.Status) && replies.has(email)) {
    const snippet = replies.get(email);
    out.push({ action: 'reply', status: stopWords.some(w => snippet.includes(w)) ? 'Opted out' : 'Replied', lead });
  }
}
const now = DateTime.now();
const followups = leads.filter(l => l.Status === 'Contacted' && !replies.has(String(l.Email).toLowerCase())
  && Number(l['Follow-ups'] || 0) < cfg.max_followups && l['Message ID']
  && l['Contacted At'] && now.diff(DateTime.fromISO(l['Contacted At']), 'days').days >= cfg.followup_after_days);
const firsts = leads.filter(l => l.Status === 'New' && l.Email && Number(l['Fit Score']) >= cfg.min_fit_score)
  .sort((a, b) => Number(b['Fit Score']) - Number(a['Fit Score']));
let budget = Number(cfg.emails_per_hour) || 5;
for (const lead of followups) { if (budget-- <= 0) break; out.push({ action: 'followup', lead }); }
for (const lead of firsts) { if (budget-- <= 0) break; out.push({ action: 'first', lead }); }
return out.map(json => ({ json }));

